pages.css:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif;
}

body {
    background: linear-gradient(135deg, #f5f7fa 0%, #e4edf5 100%);
    color: #333;
    line-height: 1.6;
    padding: 20px;
    min-height: 100vh;
    border-top: 15px solid #4ECDC4;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

header {
    text-align: center;
    margin-bottom: 40px;
    padding: 25px;
    background: linear-gradient(90deg, #FF9A9E 0%, #FAD0C4 100%);
    border-radius: 20px;
    box-shadow: 0 10px 25px rgba(255, 154, 158, 0.3);
    color: #fff;
    position: relative;
    overflow: hidden;
}

header::before {
    content: "";
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255,255,255,0.1) 1px, transparent 1px);
    background-size: 30px 30px;
    z-index: 0;
}

header h1 {
    font-size: 2.8rem;
    margin-bottom: 10px;
    position: relative;
    z-index: 1;
    text-shadow: 2px 2px 0 #FF6B8B;
}

header p {
    font-size: 1.2rem;
    opacity: 0.95;
    position: relative;
    z-index: 1;
    max-width: 800px;
    margin: 0 auto;
}

.course-icon {
    font-size: 3rem;
    margin-bottom: 15px;
    display: block;
    position: relative;
    z-index: 1;
}

.directory-container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 25px;
    margin-bottom: 50px;
}

.chapter-card {
    background: #fff;
    border-radius: 18px;
    padding: 25px;
    box-shadow: 0 8px 20px rgba(100, 181, 246, 0.2);
    transition: all 0.3s ease;
    border-left: 8px solid #FFD166;
    position: relative;
    overflow: hidden;
}

.chapter-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 30px rgba(100, 181, 246, 0.35);
    border-left-color: #06D6A0;
}

.chapter-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 5px;
    background: linear-gradient(90deg, #FFD166, #06D6A0, #118AB2);
}

.chapter-number {
    display: inline-block;
    background: #118AB2;
    color: white;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    text-align: center;
    line-height: 36px;
    font-weight: bold;
    margin-bottom: 15px;
    font-size: 1.1rem;
    box-shadow: 0 4px 8px rgba(17, 138, 178, 0.3);
}

.chapter-title {
    font-size: 1.4rem;
    margin-bottom: 15px;
    color: #073B4C;
    min-height: 65px;
    display: flex;
    align-items: center;
}

.chapter-title a {
    color: inherit;
    text-decoration: none;
    transition: color 0.2s;
}

.chapter-title a:hover {
    color: #EF476F;
    text-decoration: underline;
}

.chapter-content {
    color: #555;
    font-size: 0.95rem;
    padding-left: 5px;
    border-left: 3px dotted #FFD166;
    margin-left: 5px;
}

.chapter-content ul {
    list-style-type: none;
    padding-left: 10px;
}

.chapter-content li {
    margin-bottom: 8px;
    position: relative;
    padding-left: 20px;
}

.chapter-content li:before {
    content: "•";
    color: #06D6A0;
    font-size: 1.5rem;
    position: absolute;
    left: 0;
    top: -5px;
}

.file-link {
    display: inline-block;
    margin-top: 15px;
    background: #EF476F;
    color: white;
    padding: 8px 18px;
    border-radius: 50px;
    text-decoration: none;
    font-weight: bold;
    font-size: 0.9rem;
    transition: all 0.3s;
    box-shadow: 0 4px 10px rgba(239, 71, 111, 0.3);
}

.file-link:hover {
    background: #FF0066;
    transform: scale(1.05);
    box-shadow: 0 6px 15px rgba(239, 71, 111, 0.5);
}

.file-link i {
    margin-right: 8px;
}

footer {
    text-align: center;
    padding: 30px;
    margin-top: 40px;
    background: linear-gradient(90deg, #073B4C 0%, #118AB2 100%);
    color: white;
    border-radius: 20px;
    font-size: 1.2rem;
    box-shadow: 0 10px 25px rgba(7, 59, 76, 0.3);
    position: relative;
    overflow: hidden;
}

footer::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 5px;
    background: linear-gradient(90deg, #FFD166, #06D6A0, #EF476F);
}

.footer-content {
    position: relative;
    z-index: 1;
}

.footer-content p {
    margin: 10px 0;
}

.social-icons {
    margin-top: 15px;
}

.social-icons a {
    color: white;
    font-size: 1.5rem;
    margin: 0 15px;
    transition: all 0.3s;
    display: inline-block;
}

.social-icons a:hover {
    color: #FFD166;
    transform: translateY(-5px);
}

@media (max-width: 768px) {
    .directory-container {
        grid-template-columns: 1fr;
    }

    header h1 {
        font-size: 2.2rem;
    }

    .chapter-card {
        padding: 20px;
    }
}

.course-stats {
    display: flex;
    justify-content: center;
    gap: 30px;
    margin-top: 20px;
    flex-wrap: wrap;
}

.stat {
    background: rgba(255, 255, 255, 0.9);
    padding: 15px 25px;
    border-radius: 15px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.05);
    text-align: center;
    min-width: 150px;
}

.stat-number {
    font-size: 2.5rem;
    font-weight: bold;
    color: #118AB2;
    display: block;
    line-height: 1;
}

.stat-label {
    font-size: 0.9rem;
    color: #666;
    margin-top: 5px;
}

:root {
