    background: white;
    border: 3px solid var(--border-color);
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.05);
}
.checklist-card h4 {
    color: var(--secondary-color);
    margin-bottom: 15px;
    display: flex;
    align-items: center;
}
.checklist-card h4::before {
    content: '✓';
    background: var(--primary-color);
    color: white;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-right: 10px;
    font-size: 0.9rem;
}
.trend-item {
    background: linear-gradient(to right, #e3f2fd, #f3e5f5);
    padding: 15px;
    margin: 10px 0;
    border-radius: 10px;
    border: 2px dashed var(--secondary-color);
}
